<section class="rounded-2xl border bg-white p-5"><h2 class="font-semibold">建立 Badge 認證活動</h2><form method="POST" action="{{route('organizer.badges.store')}}" enctype="multipart/form-data" class="mt-4 grid gap-3 sm:grid-cols-2" x-data="{locationEnabled:{{old('location_claim_enabled')?'true':'false'}},locating:false,lat:'{{old('claim_lat')}}',lng:'{{old('claim_lng')}}',locate(){if(!navigator.geolocation){alert('此瀏覽器無法取得位置');return}this.locating=true;navigator.geolocation.getCurrentPosition(p=>{this.lat=p.coords.latitude.toFixed(7);this.lng=p.coords.longitude.toFixed(7);this.locating=false},()=>{this.locating=false;alert('無法取得位置，請允許定位後再試一次。')},{enableHighAccuracy:false,timeout:15000,maximumAge:60000})}}">@csrf<input name="name" required class="rounded-xl border-gray-300" placeholder="Badge 名稱"><input name="external_activity_name" required class="rounded-xl border-gray-300" placeholder="活動／賽事名稱"><input type="date" name="external_activity_date" class="rounded-xl border-gray-300"><input name="external_activity_location" class="rounded-xl border-gray-300" placeholder="活動地點"><input type="number" min="1" name="max_supply" class="rounded-xl border-gray-300" placeholder="限量數量（不限制可留空）"><input type="file" name="icon" accept="image/jpeg,image/png,image/webp" class="rounded-xl border p-2"><textarea name="description" class="rounded-xl border-gray-300 sm:col-span-2" placeholder="Badge 說明"></textarea><div class="rounded-xl border bg-gray-50 p-4 sm:col-span-2"><label class="flex items-center gap-2 font-medium"><input type="checkbox" name="location_claim_enabled" value="1" x-model="locationEnabled" class="rounded"> 開放掃描 QR Code 定位領取</label><div x-show="locationEnabled" class="mt-3 grid gap-2 sm:grid-cols-3"><input name="claim_lat" x-model="lat" :required="locationEnabled" class="rounded-xl border-gray-300" placeholder="緯度"><input name="claim_lng" x-model="lng" :required="locationEnabled" class="rounded-xl border-gray-300" placeholder="經度"><select name="claim_radius_km" class="rounded-xl border-gray-300"><option value="5">5 公里</option><option value="10" selected>10 公里</option><option value="20">20 公里</option><option value="30">30 公里</option></select><div class="sm:col-span-3"><label class="text-xs text-gray-500">單日領取（選填）</label><input type="date" name="claim_date" value="{{old('claim_date')}}" class="mt-1 min-h-11 w-full rounded-xl border-gray-300"><p class="mt-1 text-xs text-gray-500">適合活動當天；若需跨日，改填下方期間</p></div><div><label class="text-xs text-gray-500">開始時間（選填）</label><input type="datetime-local" name="claim_starts_at" value="{{old('claim_starts_at')}}" class="mt-1 min-h-11 w-full rounded-xl border-gray-300"></div><div><label class="text-xs text-gray-500">結束時間（選填）</label><input type="datetime-local" name="claim_ends_at" value="{{old('claim_ends_at')}}" class="mt-1 min-h-11 w-full rounded-xl border-gray-300"></div><p class="self-end pb-3 text-xs text-gray-500">日期與期間都未填則長期開放</p><button type="button" @click="locate()" class="min-h-11 rounded-xl border border-indigo-200 bg-white text-sm text-indigo-700 sm:col-span-3" x-text="locating?'正在取得位置…':'使用目前位置'"></button></div></div><button class="min-h-11 rounded-xl bg-indigo-600 px-5 text-white sm:col-span-2">建立</button></form></section>
<div class="grid gap-4 md:grid-cols-2">@forelse($badges as $badge)<article class="rounded-2xl border bg-white p-5"><div class="flex gap-3"><img src="{{$badge->icon_url}}" class="h-14 w-14 rounded-xl object-cover"><div class="min-w-0 flex-1"><div class="flex items-start justify-between gap-2"><h2 class="font-semibold">{{$badge->name}}</h2><span class="shrink-0 rounded-full px-2 py-1 text-xs {{$badge->is_active?'bg-green-100 text-green-700':'bg-red-100 text-red-700'}}">{{$badge->is_active?'正常':'平台停用'}}</span></div><p class="text-sm text-gray-500">{{$badge->external_activity_name}}</p><p class="text-xs text-gray-500">已發放 {{$badge->awards_count}}{{ $badge->max_supply ? '／'.$badge->max_supply : '' }}</p></div></div>@if($badge->claim_lat !== null && $badge->claim_lng !== null)<div class="mt-4 rounded-xl p-3 text-center {{!$badge->is_active?'bg-red-50':($badge->location_claim_enabled?'bg-indigo-50':'bg-yellow-50')}}">@if(!$badge->is_active)<p class="py-2 text-sm font-medium text-red-700">平台已停用此 Badge</p><p class="text-xs text-red-600">無法自行領取或發放，請聯絡平台管理員</p>@elseif($badge->location_claim_enabled)<img src="{{route('badge-drops.qrcode',$badge->claim_token)}}" class="mx-auto h-40 w-40 rounded-xl bg-white p-2" alt="定位領取 QR Code"><p class="mt-2 text-xs text-indigo-700">掃描後於 {{$badge->claim_radius_km}} 公里內自動取得</p>@if($badge->claim_starts_at || $badge->claim_ends_at)<p class="mt-1 text-xs text-indigo-700">{{$badge->claim_starts_at?->format('Y/m/d H:i') ?? '現在'}}－{{$badge->claim_ends_at?->format('Y/m/d H:i') ?? '不限'}}</p>@else<p class="mt-1 text-xs text-indigo-700">不限領取期間</p>@endif @else<p class="py-2 text-sm font-medium text-yellow-800">主辦方已停用自行領取</p><p class="text-xs text-yellow-700">既有 QR Code 暫時無法領取</p>@endif @if($badge->is_active)<form method="POST" action="{{route('organizer.badges.claim-toggle',$badge)}}" class="mt-3">@csrf @method('PATCH')<button class="min-h-11 w-full rounded-xl border bg-white text-sm font-medium {{$badge->location_claim_enabled?'border-red-200 text-red-600':'border-green-200 text-green-700'}}">{{$badge->location_claim_enabled?'停用自行領取':'重新開放自行領取'}}</button></form>@endif</div>@endif @if($badge->isAtCapacity())<p class="mt-4 rounded-xl bg-yellow-50 p-3 text-sm text-yellow-800">徽章數量已達到最大值</p>@elseif($badge->is_active)<form method="POST" action="{{route('organizer.badges.award',$badge)}}" class="mt-4 grid gap-2">@csrf<input name="member" required class="rounded-xl border-gray-300 text-sm" placeholder="會員 UUID 或 Email"><input name="note" class="rounded-xl border-gray-300 text-sm" placeholder="授予原因（選填）"><button class="min-h-11 rounded-xl bg-gray-900 text-sm text-white">發放 Badge</button></form>@endif</article>@empty<p class="text-sm text-gray-500">尚未建立獨立 Badge。</p>@endforelse</div></div>
